/* ============================================
   DROPDOWN MENU COMPONENT
   Contextual menu with sections, sub-menus,
   keyboard shortcuts, and inset-gap hover.
   Tokens aligned to Figma spec.
   ============================================ */

.ds-dropdown-menu {
  position: relative;
  display: inline-flex;
}

/* ============================================
   TRIGGER
   ============================================ */

.ds-dropdown-menu__trigger {
  display: inline-flex;
  align-items: center;
  cursor: pointer;
}

.ds-dropdown-menu__trigger:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: 2px;
  border-radius: var(--radius-200);
}

/* ============================================
   PANEL
   The floating menu container
   ============================================ */

.ds-dropdown-menu__panel {
  position: absolute;
  top: 100%;
  left: 0;
  z-index: 50;
  min-width: 200px;
  margin-top: var(--gap-050); /* 2px offset from trigger */

  /* Appearance — Figma: page/primary bg, input/border/primary, radius/md */
  background: var(--color-bg-page-primary);
  border: var(--border-025) solid var(--color-input-border-primary);
  border-radius: var(--radius-300); /* 12px */
  box-shadow: var(--shadow-floating);

  /* Inset gap — Figma: padding/xxs (4px) all sides */
  padding: var(--padding-100);

  /* Reset list */
  list-style: none;
  margin-block: 0;

  /* Animation */
  animation: ds-dropdown-menu-appear var(--motion-duration-fast) var(--motion-ease-entrance);
}

.ds-dropdown-menu__panel--align-end {
  left: auto;
  right: 0;
}

/* Compact items: paragraph-sm-em (14/20), padding xs sm-md (6px 12px), radius-sm (8px) */
.ds-dropdown-menu__panel--compact .ds-dropdown-menu__item {
  padding: var(--padding-150) var(--padding-300); /* 6px 12px */
  border-radius: var(--radius-200); /* 8px */
  font-family: var(--font-paragraph-sm-emphasis-family);
  font-size: var(--font-paragraph-sm-emphasis-size);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  line-height: var(--font-paragraph-sm-emphasis-line-height);
  letter-spacing: var(--font-paragraph-sm-emphasis-letter-spacing);
}

/* Compact icons: 20px (vs 24px default) */
.ds-dropdown-menu__panel--compact .ds-dropdown-menu__item-icon {
  --icon-size: var(--icon-size-500);
}

/* Compact submenu chevron: 20px */
.ds-dropdown-menu__panel--compact .ds-dropdown-menu__submenu-icon {
  --icon-size: var(--icon-size-500);
}

/* Compact group label: same padding as compact items so heights match */
.ds-dropdown-menu__panel--compact .ds-dropdown-menu__group-label {
  min-height: auto;
  padding: var(--padding-150) var(--padding-300); /* matches compact item padding */
  font-size: var(--font-paragraph-sm-emphasis-size);
  line-height: var(--font-paragraph-sm-emphasis-line-height);
  letter-spacing: var(--font-paragraph-sm-emphasis-letter-spacing);
}

/* Compact separator margin matches compact item padding */
.ds-dropdown-menu__panel--compact .ds-dropdown-menu__separator {
  margin: var(--padding-100) var(--padding-300);
}

/* Compact shortcuts keep the base --font-paragraph-sm-* size — the scale
   has no smaller step. */

/* ============================================
   SUB-MENU PANEL
   ============================================ */

.ds-dropdown-menu__submenu {
  position: absolute;
  left: 100%;
  top: 0;
  margin-left: var(--gap-050); /* 4px offset from parent */
}

/* ============================================
   MENU ITEM
   Figma: Button/secondary internally —
   padding/sm (8px) vertical, padding/md (16px) horizontal,
   radius/md (12px), paragraph-em typography.
   ============================================ */

.ds-dropdown-menu__item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--gap-400); /* 16px between label and shortcut */
  padding: var(--padding-200) var(--padding-400); /* Figma: 8px 16px */
  border-radius: var(--radius-300); /* Figma: 12px */
  cursor: pointer;
  position: relative;
  white-space: nowrap;
  list-style: none;

  /* Typography — paragraph em (medium weight, matches Figma Button secondary) */
  font-family: var(--font-paragraph-emphasis-family);
  font-size: var(--font-paragraph-emphasis-size);
  font-weight: var(--font-paragraph-emphasis-weight);
  line-height: var(--font-paragraph-emphasis-line-height);
  letter-spacing: var(--font-paragraph-emphasis-letter-spacing);
  color: var(--color-action-passive-text);

  transition: background-color var(--motion-duration-fast) var(--motion-ease-standard), color var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-dropdown-menu__item:hover,
.ds-dropdown-menu__item--focused {
  background-color: var(--color-action-passive-bg-hover);
}

/* ============================================
   SELECTED ITEM
   The current choice of a set: the passive wash held down, text and icon
   at full strength, and a trailing check — three cues, none of them the
   action colour, which a menu row has no claim on.
   ============================================ */

.ds-dropdown-menu__item--selected {
  background-color: var(--color-action-passive-bg-hover);
  color: var(--color-text-primary);
}

.ds-dropdown-menu__item--selected:hover,
.ds-dropdown-menu__item--selected.ds-dropdown-menu__item--focused {
  background-color: var(--color-action-passive-bg-active);
}

.ds-dropdown-menu__item--selected .ds-dropdown-menu__item-icon {
  color: var(--color-icon-primary);
}

.ds-dropdown-menu__check {
  --icon-size: var(--icon-size-500);
  color: var(--color-icon-primary);
  margin-left: auto;
  flex-shrink: 0;
  line-height: 1;
}

/* ============================================
   DISABLED ITEM
   ============================================ */

.ds-dropdown-menu__item--disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.ds-dropdown-menu__item--disabled:hover,
.ds-dropdown-menu__item--disabled.ds-dropdown-menu__item--focused {
  background-color: transparent;
}

/* ============================================
   ITEM LABEL (text + optional icon)
   ============================================ */

.ds-dropdown-menu__item-label {
  display: flex;
  align-items: center;
  gap: var(--gap-200); /* Figma: 8px between icon and text */
  line-height: 1;
}

/* Figma: icons are 24px within menu items */
.ds-dropdown-menu__item-icon {
  --icon-size: var(--icon-size-600);
  color: var(--color-icon-secondary);
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

/* ============================================
   KEYBOARD SHORTCUT
   ============================================ */

.ds-dropdown-menu__shortcut {
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  color: var(--color-text-tertiary);
  margin-left: auto;
  flex-shrink: 0;
}

/* ============================================
   SUB-MENU INDICATOR
   Figma: 24px chevron icon
   ============================================ */

.ds-dropdown-menu__submenu-icon {
  --icon-size: var(--icon-size-600);
  color: var(--color-text-tertiary);
  margin-left: auto;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

/* ============================================
   SEPARATOR
   ============================================ */

.ds-dropdown-menu__separator {
  height: 1px;
  background: var(--color-input-border-primary);
  margin: var(--padding-100) var(--padding-400);
  list-style: none;
}

/* ============================================
   GROUP
   ============================================ */

.ds-dropdown-menu__group {
  list-style: none;
}

/* Figma: section label is paragraph-em at text/tertiary,
   40px height container, padding-left aligns with item text */
.ds-dropdown-menu__group-label {
  display: flex;
  align-items: center;
  min-height: 40px;
  font-family: var(--font-paragraph-emphasis-family);
  font-size: var(--font-paragraph-emphasis-size);
  font-weight: var(--font-paragraph-emphasis-weight);
  line-height: var(--font-paragraph-emphasis-line-height);
  letter-spacing: var(--font-paragraph-emphasis-letter-spacing);
  color: var(--color-text-tertiary);
  padding-left: var(--padding-400);
  padding-right: var(--padding-400);
  user-select: none;
}

.ds-dropdown-menu__group-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

/* ============================================
   HAS-SUBMENU ITEM
   ============================================ */

.ds-dropdown-menu__item--has-submenu {
  padding-right: var(--padding-300); /* Slightly less right padding for chevron */
}

/* ============================================
   DESTRUCTIVE ITEM
   Red text/icon for dangerous actions (delete, remove…)
   ============================================ */

.ds-dropdown-menu__item--destructive {
  color: var(--color-core-accent-coral);
}

.ds-dropdown-menu__item--destructive .ds-dropdown-menu__item-icon {
  color: var(--color-core-accent-coral);
}

.ds-dropdown-menu__item--destructive .ds-dropdown-menu__shortcut {
  color: var(--color-core-accent-coral);
  opacity: 0.7;
}

.ds-dropdown-menu__item--destructive:hover,
.ds-dropdown-menu__item--destructive.ds-dropdown-menu__item--focused {
  background-color: var(--color-status-error-bg);
}

/* ============================================
   APPEAR ANIMATION
   ============================================ */

@keyframes ds-dropdown-menu-appear {
  from {
    opacity: 0;
    transform: scale(0.96);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

'use client';

import React, { useState, useRef, useEffect, useCallback, useId } from 'react';
import { MOTION_HOVER_HIDE_DELAY_MS } from '../../tokens/motion';
import './DropdownMenu.css';
import '../../fonts/material-symbols.css';

/* ============================================
   TYPES
   ============================================ */

export interface DropdownMenuItem {
  type?: 'item';
  /** Display label */
  label: string;
  /** Keyboard shortcut hint (e.g. "⇧ ⌘ P") */
  shortcut?: string;
  /** Item icon — Material Symbol name (string) or custom element (ReactNode) */
  icon?: string | React.ReactNode;
  /** Disabled state */
  disabled?: boolean;
  /** Destructive / danger styling (red text) for delete, remove, etc. */
  destructive?: boolean;
  /** Marks the item as the current choice of a set: it holds the passive wash and a trailing check, and is announced as a checked radio item. Leave undefined on plain action items; pass `false` on the unchosen members of a set so they are announced as radio items too. Ignored on an item that opens a sub-menu. */
  selected?: boolean;
  /** Click handler */
  onClick?: () => void;
  /** Nested sub-menu items */
  children?: DropdownMenuEntry[];
}

export interface DropdownMenuSeparator {
  type: 'separator';
}

export interface DropdownMenuGroup {
  type: 'group';
  /** Section heading */
  label: string;
  /** Items within the group */
  items: DropdownMenuEntry[];
}

export type DropdownMenuEntry =
  | DropdownMenuItem
  | DropdownMenuSeparator
  | DropdownMenuGroup;

export interface DropdownMenuProps {
  /** Trigger element that opens the menu */
  trigger: React.ReactNode;
  /** Menu entries (items, groups, separators) */
  items: DropdownMenuEntry[];
  /** Horizontal alignment of the panel */
  align?: 'start' | 'end';
  /** Component size */
  size?: 'default' | 'compact';
  /** Additional CSS classes */
  className?: string;
}

/* ============================================
   HELPERS
   ============================================ */

/** Flatten all actionable items from entries for keyboard navigation */
function collectItems(entries: DropdownMenuEntry[]): DropdownMenuItem[] {
  const result: DropdownMenuItem[] = [];
  for (const entry of entries) {
    if (entry.type === 'separator') continue;
    if (entry.type === 'group') {
      result.push(...collectItems(entry.items));
    } else {
      result.push(entry);
    }
  }
  return result;
}

/* ============================================
   SUB-MENU ITEM
   ============================================ */

interface SubMenuItemProps {
  item: DropdownMenuItem;
  baseClass: string;
  itemId: string;
  focused: boolean;
  size: 'default' | 'compact';
  onActivate: () => void;
}

const SubMenuItem = ({ item, baseClass, itemId, focused, size, onActivate }: SubMenuItemProps) => {
  const [subOpen, setSubOpen] = useState(false);
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const handleMouseEnter = () => {
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    setSubOpen(true);
  };

  const handleMouseLeave = () => {
    timeoutRef.current = setTimeout(() => setSubOpen(false), MOTION_HOVER_HIDE_DELAY_MS);
  };

  useEffect(() => {
    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, []);

  // Open sub-menu when focused via keyboard
  useEffect(() => {
    if (focused && item.children && item.children.length > 0) {
      // eslint-disable-next-line react-hooks/set-state-in-effect -- syncing submenu visibility to keyboard focus arriving from the parent menu
      setSubOpen(true);
    }
  }, [focused, item.children]);

  const classes = [
    `${baseClass}__item`,
    focused ? `${baseClass}__item--focused` : '',
    item.disabled ? `${baseClass}__item--disabled` : '',
    item.destructive ? `${baseClass}__item--destructive` : '',
    `${baseClass}__item--has-submenu`,
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <li
      id={itemId}
      className={classes}
      role="menuitem"
      aria-haspopup="menu"
      aria-expanded={subOpen}
      aria-disabled={item.disabled || undefined}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      onClick={(e) => {
        e.stopPropagation();
        if (!item.disabled) setSubOpen((prev) => !prev);
      }}
    >
      <span className={`${baseClass}__item-label`}>
        {item.icon &&
          (typeof item.icon === 'string' ? (
            <span className={`${baseClass}__item-icon material-symbols-rounded`} aria-hidden="true">
              {item.icon}
            </span>
          ) : (
            <span className={`${baseClass}__item-icon`} aria-hidden="true">
              {item.icon}
            </span>
          ))}
        {item.label}
      </span>
      <span className={`${baseClass}__submenu-icon material-symbols-rounded`} aria-hidden="true">
        chevron_right
      </span>
      {subOpen && item.children && (
        <MenuPanel
          entries={item.children}
          baseClass={baseClass}
          itemIdBase={`${itemId}-sub`}
          size={size}
          isSubmenu
          onItemActivate={onActivate}
        />
      )}
    </li>
  );
};

/* ============================================
   MENU PANEL (reusable for root + sub-menus)
   ============================================ */

interface MenuPanelProps {
  entries: DropdownMenuEntry[];
  baseClass: string;
  itemIdBase: string;
  size: 'default' | 'compact';
  isSubmenu?: boolean;
  onItemActivate: () => void;
}

const MenuPanel = ({
  entries,
  baseClass,
  itemIdBase,
  size,
  isSubmenu = false,
  onItemActivate,
}: MenuPanelProps) => {
  const panelClasses = [
    `${baseClass}__panel`,
    isSubmenu ? `${baseClass}__submenu` : '',
    size === 'compact' ? `${baseClass}__panel--compact` : '',
  ]
    .filter(Boolean)
    .join(' ');

  const renderEntry = (entry: DropdownMenuEntry, index: number, idBase: string) => {
    const entryId = `${idBase}-${index}`;

    if (entry.type === 'separator') {
      return <li key={`sep-${index}`} className={`${baseClass}__separator`} role="separator" />;
    }

    if (entry.type === 'group') {
      return (
        <li key={`group-${index}`} className={`${baseClass}__group`} role="group" aria-label={entry.label}>
          <span className={`${baseClass}__group-label`}>{entry.label}</span>
          <ul className={`${baseClass}__group-list`} role="group">
            {entry.items.map((subEntry, subIndex) => renderEntry(subEntry, subIndex, entryId))}
          </ul>
        </li>
      );
    }

    // Item with children → sub-menu
    if (entry.children && entry.children.length > 0) {
      return (
        <SubMenuItem
          key={`submenu-${index}`}
          item={entry}
          baseClass={baseClass}
          itemId={entryId}
          focused={false}
          size={size}
          onActivate={onItemActivate}
        />
      );
    }

    // Regular item
    const itemClasses = [
      `${baseClass}__item`,
      entry.disabled ? `${baseClass}__item--disabled` : '',
      entry.destructive ? `${baseClass}__item--destructive` : '',
      entry.selected ? `${baseClass}__item--selected` : '',
    ]
      .filter(Boolean)
      .join(' ');

    // `selected` given at all means the item belongs to a choice set.
    const isChoice = entry.selected !== undefined;

    return (
      <li
        key={`item-${index}`}
        id={entryId}
        className={itemClasses}
        role={isChoice ? 'menuitemradio' : 'menuitem'}
        aria-checked={isChoice ? entry.selected : undefined}
        aria-disabled={entry.disabled || undefined}
        onClick={(e) => {
          e.stopPropagation();
          if (!entry.disabled) {
            entry.onClick?.();
            onItemActivate();
          }
        }}
      >
        <span className={`${baseClass}__item-label`}>
          {entry.icon &&
            (typeof entry.icon === 'string' ? (
              <span className={`${baseClass}__item-icon material-symbols-rounded`} aria-hidden="true">
                {entry.icon}
              </span>
            ) : (
              <span className={`${baseClass}__item-icon`} aria-hidden="true">
                {entry.icon}
              </span>
            ))}
          {entry.label}
        </span>
        {entry.shortcut && (
          <span className={`${baseClass}__shortcut`}>{entry.shortcut}</span>
        )}
        {entry.selected && (
          <span className={`${baseClass}__check material-symbols-rounded`} aria-hidden="true">
            check
          </span>
        )}
      </li>
    );
  };

  return (
    <ul className={panelClasses} role="menu">
      {entries.map((entry, index) => renderEntry(entry, index, itemIdBase))}
    </ul>
  );
};

/* ============================================
   DROPDOWN MENU — ROOT COMPONENT
   ============================================ */

export const DropdownMenu = ({
  trigger,
  items,
  align = 'start',
  size = 'default',
  className = '',
}: DropdownMenuProps) => {
  const [isOpen, setIsOpen] = useState(false);
  const [focusedIndex, setFocusedIndex] = useState(-1);
  const rootRef = useRef<HTMLDivElement>(null);
  const panelRef = useRef<HTMLUListElement | null>(null);
  const generatedId = useId();

  const baseClass = 'ds-dropdown-menu';
  const classes = [baseClass, className].filter(Boolean).join(' ');

  const flatItems = collectItems(items);

  const menuId = `${generatedId}-menu`;
  const activeDescendantId =
    isOpen && focusedIndex >= 0 ? `${generatedId}-item-${focusedIndex}` : undefined;

  const handleToggle = () => {
    setIsOpen((prev) => {
      if (!prev) setFocusedIndex(-1);
      return !prev;
    });
  };

  const handleClose = useCallback(() => {
    setIsOpen(false);
    setFocusedIndex(-1);
  }, []);

  /* Click outside */
  useEffect(() => {
    if (!isOpen) return;
    const handler = (e: MouseEvent) => {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) {
        handleClose();
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, [isOpen, handleClose]);

  /* Keyboard navigation */
  const handleKeyDown = (e: React.KeyboardEvent) => {
    switch (e.key) {
      case 'Enter':
      case ' ':
        e.preventDefault();
        if (!isOpen) {
          setIsOpen(true);
          setFocusedIndex(0);
        } else if (focusedIndex >= 0) {
          const item = flatItems[focusedIndex];
          if (item && !item.disabled && !item.children) {
            item.onClick?.();
            handleClose();
          }
        }
        break;
      case 'ArrowDown':
        e.preventDefault();
        if (!isOpen) {
          setIsOpen(true);
          setFocusedIndex(0);
        } else {
          setFocusedIndex((prev) => {
            let next = prev + 1;
            while (next < flatItems.length && flatItems[next].disabled) next++;
            return next < flatItems.length ? next : prev;
          });
        }
        break;
      case 'ArrowUp':
        e.preventDefault();
        if (isOpen) {
          setFocusedIndex((prev) => {
            let next = prev - 1;
            while (next >= 0 && flatItems[next].disabled) next--;
            return next >= 0 ? next : prev;
          });
        }
        break;
      case 'Home':
        if (isOpen) {
          e.preventDefault();
          setFocusedIndex((prev) => {
            let next = 0;
            while (next < flatItems.length && flatItems[next].disabled) next++;
            return next < flatItems.length ? next : prev;
          });
        }
        break;
      case 'End':
        if (isOpen) {
          e.preventDefault();
          setFocusedIndex((prev) => {
            let next = flatItems.length - 1;
            while (next >= 0 && flatItems[next].disabled) next--;
            return next >= 0 ? next : prev;
          });
        }
        break;
      case 'Escape':
      case 'Tab':
        handleClose();
        break;
    }
  };

  /* Scroll focused item into view */
  useEffect(() => {
    if (isOpen && focusedIndex >= 0 && panelRef.current) {
      const allItems = panelRef.current.querySelectorAll(`[role="menuitem"], [role="menuitemradio"]`);
      const el = allItems[focusedIndex] as HTMLElement | undefined;
      el?.scrollIntoView({ block: 'nearest' });
    }
  }, [focusedIndex, isOpen]);

  /* Render the panel with focus tracking */
  const renderPanelEntry = (entry: DropdownMenuEntry, index: number, itemCounter: { count: number }) => {
    if (entry.type === 'separator') {
      return <li key={`sep-${index}`} className={`${baseClass}__separator`} role="separator" />;
    }

    if (entry.type === 'group') {
      return (
        <li key={`group-${index}`} className={`${baseClass}__group`} role="none">
          <span className={`${baseClass}__group-label`} role="presentation">{entry.label}</span>
          <ul className={`${baseClass}__group-list`} role="group" aria-label={entry.label}>
            {entry.items.map((subEntry, subIndex) =>
              renderPanelEntry(subEntry, subIndex, itemCounter)
            )}
          </ul>
        </li>
      );
    }

    const myIndex = itemCounter.count;
    itemCounter.count++;
    const isFocused = myIndex === focusedIndex;

    // Sub-menu item
    if (entry.children && entry.children.length > 0) {
      return (
        <SubMenuItem
          key={`submenu-${index}`}
          item={entry}
          baseClass={baseClass}
          itemId={`${generatedId}-item-${myIndex}`}
          focused={isFocused}
          size={size}
          onActivate={handleClose}
        />
      );
    }

    // Regular item
    const itemClasses = [
      `${baseClass}__item`,
      isFocused ? `${baseClass}__item--focused` : '',
      entry.disabled ? `${baseClass}__item--disabled` : '',
      entry.destructive ? `${baseClass}__item--destructive` : '',
      entry.selected ? `${baseClass}__item--selected` : '',
    ]
      .filter(Boolean)
      .join(' ');

    // `selected` given at all means the item belongs to a choice set.
    const isChoice = entry.selected !== undefined;

    return (
      <li
        key={`item-${index}`}
        id={`${generatedId}-item-${myIndex}`}
        className={itemClasses}
        role={isChoice ? 'menuitemradio' : 'menuitem'}
        aria-checked={isChoice ? entry.selected : undefined}
        aria-disabled={entry.disabled || undefined}
        onClick={(e) => {
          e.stopPropagation();
          if (!entry.disabled) {
            entry.onClick?.();
            handleClose();
          }
        }}
      >
        <span className={`${baseClass}__item-label`}>
          {entry.icon &&
            (typeof entry.icon === 'string' ? (
              <span className={`${baseClass}__item-icon material-symbols-rounded`} aria-hidden="true">
                {entry.icon}
              </span>
            ) : (
              <span className={`${baseClass}__item-icon`} aria-hidden="true">
                {entry.icon}
              </span>
            ))}
          {entry.label}
        </span>
        {entry.shortcut && (
          <span className={`${baseClass}__shortcut`}>{entry.shortcut}</span>
        )}
        {entry.selected && (
          <span className={`${baseClass}__check material-symbols-rounded`} aria-hidden="true">
            check
          </span>
        )}
      </li>
    );
  };

  const panelClasses = [
    `${baseClass}__panel`,
    align === 'end' ? `${baseClass}__panel--align-end` : '',
    size === 'compact' ? `${baseClass}__panel--compact` : '',
  ]
    .filter(Boolean)
    .join(' ');

  const itemCounter = { count: 0 };

  // A consumer's own handlers on the trigger element must keep firing —
  // cloneElement replaces props, so compose rather than overwrite.
  const triggerProps = React.isValidElement(trigger)
    ? (trigger.props as {
        onClick?: React.MouseEventHandler;
        onKeyDown?: React.KeyboardEventHandler;
      })
    : undefined;

  return (
    <div className={classes} ref={rootRef}>
      {/*
        The trigger is consumer-supplied and is virtually always already a
        control (a Button). Wrapping it in role="button" tabIndex=0 put an
        interactive element inside an interactive container. Put the menu
        semantics on the real control instead, and only synthesise a button
        when the trigger is not an element we can clone onto.
      */}
      <div className={`${baseClass}__trigger`}>
        {React.isValidElement(trigger) ? (
          React.cloneElement(trigger as React.ReactElement<Record<string, unknown>>, {
            'aria-haspopup': 'menu',
            'aria-expanded': isOpen,
            'aria-controls': isOpen ? menuId : undefined,
            'aria-activedescendant': activeDescendantId,
            onClick: (e: React.MouseEvent) => {
              triggerProps?.onClick?.(e);
              handleToggle();
            },
            onKeyDown: (e: React.KeyboardEvent) => {
              triggerProps?.onKeyDown?.(e);
              handleKeyDown(e);
            },
          })
        ) : (
          <button
            type="button"
            aria-haspopup="menu"
            aria-expanded={isOpen}
            aria-controls={isOpen ? menuId : undefined}
            aria-activedescendant={activeDescendantId}
            onClick={handleToggle}
            onKeyDown={handleKeyDown}
          >
            {trigger}
          </button>
        )}
      </div>
      {isOpen && (
        <ul
          id={menuId}
          className={panelClasses}
          role="menu"
          ref={(el) => {
            panelRef.current = el;
          }}
        >
          {items.map((entry, index) => renderPanelEntry(entry, index, itemCounter))}
        </ul>
      )}
    </div>
  );
};
